mapper.select:
select c.complaint_id as complaintId, c.member_id as memberId, m.member_name as memberName, m.user_id as userId, m.email, m.phone, c.title, c.content, c.complaint_type as complaintType, c.priority, c.status, c.station_id as stationId, c.charger_id as chargerId, c.station_name as stationName, c.charger_name as chargerName, c.assigned_department_id as assignedDepartmentId, d.department_name as assignedDepartmentName, c.assigned_employee_id as assignedEmployeeId, am.member_name as assignedEmployeeName, c.ai_summary as aiSummary, c.admin_memo as adminMemo, c.created_at as createdAt, c.updated_at as updatedAt, c.closed_at as closedAt from complaint c join app_member m on c.member_id = m.member_id left join department d on c.assigned_department_id = d.department_id left join employee e on c.assigned_employee_id = e.employee_id left join app_member am on e.member_id = am.member_id where 1 = 1
and c.status = #{status}
and c.complaint_type = #{complaintType}
and c.priority = #{priority}
and c.station_id = #{stationId}
and c.charger_id = #{chargerId}
and ( c.title ilike concat('%', #{keyword}, '%') or c.content ilike concat('%', #{keyword}, '%') or c.station_name ilike concat('%', #{keyword}, '%') or c.charger_name ilike concat('%', #{keyword}, '%') or m.member_name ilike concat('%', #{keyword}, '%') or m.user_id ilike concat('%', #{keyword}, '%') )
order by c.created_at desc
